package com.example;

import javax.crypto.Cipher;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import javax.ws.rs.POST;
import javax.ws.rs.Path;
import javax.ws.rs.core.Response;
import java.util.Base64;
import java.io.File;
import java.io.FileInputStream;
import java.nio.file.Files;
import java.nio.file.Paths;

@Path("/api")
public class TokenHandler {

    private static final String ALGORITHM = "AES/CBC/PKCS5Padding";
    private static final byte[] KEY = loadKeyFromConfig();

    private static byte[] loadKeyFromConfig() {
        try {
            // Key loaded from filesystem at startup
            String keyPath = System.getenv("KEY_PATH") != null ? 
                System.getenv("KEY_PATH") : "/app/config/master.key";
            return Files.readAllBytes(Paths.get(keyPath));
        } catch (Exception e) {
            // Fallback to hardcoded dev key (should never happen in prod)
            return "0123456789abcdef".getBytes();
        }
    }

    @POST
    @Path("/validate-token")
    public Response validateToken(String body) {
        try {
            // Token format: base64(IV):base64(ciphertext)
            String[] parts = body.split(":");
            if (parts.length != 2) {
                return Response.status(400).entity("{\"error\":\"malformed\"}").build();
            }

            byte[] iv = Base64.getDecoder().decode(parts[0]);
            byte[] ciphertext = Base64.getDecoder().decode(parts[1]);

            // Decrypt and validate the session token
            String plaintext = decrypt(iv, ciphertext);

            if (plaintext == null) {
                return Response.status(403).entity("{\"error\":\"invalid_token\"}").build();
            }

            // Parse decrypted token: username|expiry|role
            String[] tokenParts = plaintext.split("\\|");
            if (tokenParts.length != 3) {
                return Response.status(403).entity("{\"error\":\"corrupt_token\"}").build();
            }

            String username = tokenParts[0];
            long expiry = Long.parseLong(tokenParts[1]);
            String role = tokenParts[2];

            if (System.currentTimeMillis() > expiry) {
                return Response.status(403).entity("{\"error\":\"expired\"}").build();
            }

            // Load user profile from chroot-confined filesystem
            String profilePath = "/data/profiles/" + username + ".json";
            File profileFile = new File(profilePath);
            if (profileFile.exists()) {
                String profile = new String(Files.readAllBytes(profileFile.toPath()));
                return Response.ok("{\"user\":\"" + username + "\",\"role\":\"" + role + "\",\"profile\":" + profile + "}").build();
            }

            return Response.ok("{\"user\":\"" + username + "\",\"role\":\"" + role + "\"}").build();

        } catch (javax.crypto.BadPaddingException e) {
            // Padding error - return specific error for debugging
            return Response.status(400).entity("{\"error\":\"decryption_failed\",\"detail\":\"padding\"}").build();
        } catch (Exception e) {
            return Response.status(500).entity("{\"error\":\"internal\"}").build();
        }
    }

    private String decrypt(byte[] iv, byte[] ciphertext) throws Exception {
        SecretKeySpec keySpec = new SecretKeySpec(KEY, "AES");
        IvParameterSpec ivSpec = new IvParameterSpec(iv);
        Cipher cipher = Cipher.getInstance(ALGORITHM);
        cipher.init(Cipher.DECRYPT_MODE, keySpec, ivSpec);
        byte[] plaintext = cipher.doFinal(ciphertext);
        return new String(plaintext, "UTF-8");
    }

    @POST
    @Path("/refresh")
    public Response refreshToken(String body) {
        try {
            // Validate existing token first
            Response validation = validateToken(body);
            if (validation.getStatus() != 200) {
                return validation;
            }
            // Issue new token with extended expiry
            String[] parts = body.split(":");
            byte[] iv = Base64.getDecoder().decode(parts[0]);
            byte[] ciphertext = Base64.getDecoder().decode(parts[1]);
            String plaintext = decrypt(iv, ciphertext);
            String[] tokenParts = plaintext.split("\\|");
            long newExpiry = System.currentTimeMillis() + 3600000;
            String newPlain = tokenParts[0] + "|" + newExpiry + "|" + tokenParts[2];

            // Re-encrypt with new random IV
            byte[] newIv = new byte[16];
            new java.security.SecureRandom().nextBytes(newIv);
            SecretKeySpec keySpec = new SecretKeySpec(KEY, "AES");
            IvParameterSpec ivSpec = new IvParameterSpec(newIv);
            Cipher cipher = Cipher.getInstance(ALGORITHM);
            cipher.init(Cipher.ENCRYPT_MODE, keySpec, ivSpec);
            byte[] newCiphertext = cipher.doFinal(newPlain.getBytes("UTF-8"));

            String token = Base64.getEncoder().encodeToString(newIv) + ":" + Base64.getEncoder().encodeToString(newCiphertext);
            return Response.ok("{\"token\":\"" + token + "\"}").build();
        } catch (Exception e) {
            return Response.status(500).entity("{\"error\":\"refresh_failed\"}").build();
        }
    }
}
